func finalizeJetStreamMessage(msg *nats.Msg, hErr error, policy deliveryPolicy) {
	if msg == nil {
		return
	}
	meta, err := msg.Metadata()
	if hErr != nil {
		if err == nil && policy.MaxDeliver > 0 && meta.NumDelivered >= uint64(policy.MaxDeliver) {
			if policy.Logger != nil {
				policy.Logger.Error("poison pill message exhausted max_deliver, terminating",
					zap.String("subject", msg.Subject),
					zap.Uint64("delivered", meta.NumDelivered),
					zap.Int("worker_id", policy.WorkerID),
					zap.Error(hErr),
				)
			}
			_ = msg.Term()
			return
		}
		delay := policy.NakDelay
		if delay <= 0 {
			delay = 2 * time.Second
		}
		if err == nil && meta.NumDelivered > 1 {
			delay = time.Duration(meta.NumDelivered) * delay
		}
		if policy.Logger != nil {
			policy.Logger.Warn("transmute task handler failed, nak with delay",
				zap.String("subject", msg.Subject),
				zap.Int("worker_id", policy.WorkerID),
				zap.Duration("nak_delay", delay),
				zap.Error(hErr),
			)
		}
		_ = msg.NakWithDelay(delay)
		return
	}
	_ = msg.Ack()
}

